209	// declaredPushDestination resolves where a bare `git push` on the current
210	// branch would go. Empty when HEAD is detached or nothing is declared.
211	//
212	// Phase-1 simplification: the pre-push hook receives only the remote name
213	// (refspecs are not plumbed through), so the declaration is read from HEAD's
214	// branch rather than the branches actually being pushed. A miss is
215	// conservative — no capture happens and the gate behaves as before.
216	func declaredPushDestination(ctx context.Context) string {
217		out, err := exec.CommandContext(ctx, "git", "symbolic-ref", "--short", "HEAD").Output()
218		if err != nil {
219			return ""
220		}
221		return DeclaredPushRemoteForBranch(ctx, strings.TrimSpace(string(out)))
222	}
223	
224	// DeclaredPushRemoteForBranch resolves where `git push` would send branch,
225	// through git's own precedence: branch.<name>.pushRemote, then
226	// remote.pushDefault, then branch.<name>.remote. Empty when branch is empty or
227	// nothing is declared — callers supply their own default, since the right one
228	// differs per caller ("origin" for a command issuing its own push; "no capture"
229	// for the checkpoint gate).
230	//
231	// This is the "where does this branch push" question, which is NOT the question
232	// ResolveCheckpointSyncRemote answers ("which single remote may carry checkpoint
233	// data"). Do not substitute one for the other in either direction; that
234	// resolver's doc comment holds the full argument, including why checkpoint sync
235	// deliberately does not elect from the declaration returned here. The short
236	// version: that objection is about a gate deciding whether to piggyback on
237	// someone else's push, and does not apply to a caller issuing its own.
238	func DeclaredPushRemoteForBranch(ctx context.Context, branch string) string {
239		if branch == "" {
240			return ""
241		}
242		if v := gitConfigValue(ctx, "branch."+branch+".pushRemote"); v != "" {
243			return v
244		}
245		if v := gitConfigValue(ctx, "remote.pushDefault"); v != "" {
246			return v
247		}
248		return gitConfigValue(ctx, "branch."+branch+".remote")
249	}
250	
251	// gitConfigValue returns a single git config value, or "" when unset or on
252	// any error.
253	func gitConfigValue(ctx context.Context, key string) string {
254		out, err := exec.CommandContext(ctx, "git", "config", "--get", key).Output()
255		if err != nil {
256			return ""
257		}
258		return strings.TrimSpace(string(out))
259	}

